def _rsync_dest(args: list[str]) -> list[str]:
    opts, ops = _split_opts(args, "TBefM", _RSYNC_VALUE, _RSYNC_FLAGS)
    out = _vals(opts, "--partial-dir", "--backup-dir", "--temp-dir", "-T", "--log-file",
                "--write-batch", "--only-write-batch")  # fmt: skip
    if len(ops) >= 2:
        dest = ops[-1]
